import { useEffect, useMemo, useRef, useState, type KeyboardEvent } from 'react'
import { cannotDecide, judgeItem, planDigest, RISK_ORDER, STATUS_ORDER, type Decision, type DecisionKind, type ItemStatus, type QueueItem } from './approval'
import { formatDuration } from './chart'
import { Check, Cross } from './icons'
import { JsonTree } from './JsonTree'
import { cx, formatWhen } from './util'

export type { QueueItem, Decision, DecisionKind }
export type ApprovalQueueProps = {
  title: string
  items: QueueItem[]
  /** Who is looking. They cannot decide their own requests or decide twice. */
  reviewer: string
  now?: string | Date
  /** Hide other reviewers' decisions until this reviewer has decided, so a second approval is an independent one. */
  blind?: boolean
  onDecide?: (id: string, decision: DecisionKind, planHash: string) => void
  defaultSelected?: string
  className?: string
}

const STATUS_WORD: Record<ItemStatus, { text: string; tone?: 'good' | 'warn' | 'bad' }> = {
  pending: { text: 'Waiting', tone: 'warn' }, partial: { text: 'Needs another approval', tone: 'warn' }, approved: { text: 'Approved', tone: 'good' },
  rejected: { text: 'Rejected', tone: 'bad' }, escalated: { text: 'Escalated', tone: 'good' }, expired: { text: 'Expired', tone: 'bad' }, stale: { text: 'Plan changed', tone: 'bad' },
}

/**
 * A review queue where an approval is bound to the exact plan. The plan is hashed, every decision records the
 * hash it was made on, and a decision on an older version stops counting the moment the plan changes. Buttons
 * say what will happen, the page says whether it can be undone and what evidence was checked, a second
 * approval must come from a different person, and anything not decided in time expires instead of going through.
 */
export function ApprovalQueue({ title, items, reviewer, now, blind = false, onDecide, defaultSelected, className }: ApprovalQueueProps) {
  const clock = now ? new Date(now) : new Date()
  const [hashes, setHashes] = useState<Record<string, string>>({})
  const [local, setLocal] = useState<Record<string, Decision[]>>({})
  const [selected, setSelected] = useState<string | undefined>(defaultSelected ?? items[0]?.id)
  const body = useRef<HTMLDivElement>(null)

  useEffect(() => {
    let live = true
    Promise.all(items.map(async (i) => [i.id, await planDigest(i.plan)] as const)).then((pairs) => { if (live) setHashes(Object.fromEntries(pairs)) })
    return () => { live = false }
  }, [items])

  const full = useMemo(() => items.map((i) => ({ ...i, decisions: [...i.decisions, ...(local[i.id] ?? [])] })), [items, local])
  const rows = full.map((item) => ({ item, hash: hashes[item.id], judged: hashes[item.id] ? judgeItem(item, hashes[item.id]!, clock) : null }))
  const ordered = [...rows].sort((a, b) => (a.judged ? STATUS_ORDER[a.judged.status] : 1) - (b.judged ? STATUS_ORDER[b.judged.status] : 1) || RISK_ORDER[a.item.risk] - RISK_ORDER[b.item.risk])
  const cur = ordered.find((r) => r.item.id === selected) ?? ordered[0]
  const open = ordered.filter((r) => r.judged && ['pending', 'partial', 'stale'].includes(r.judged.status)).length

  const decide = (kind: DecisionKind) => {
    if (!cur?.hash || !cur.judged || cannotDecide(cur.item, cur.judged, reviewer)) return
    const d: Decision = { by: reviewer, decision: kind, at: clock.toISOString(), planHash: cur.hash }
    setLocal((l) => ({ ...l, [cur.item.id]: [...(l[cur.item.id] ?? []), d] }))
    onDecide?.(cur.item.id, kind, cur.hash)
  }
  const onKey = (e: KeyboardEvent<HTMLDivElement>) => {
    if ((e.target as HTMLElement).closest('input,textarea,button[role="treeitem"],.ic-json')) return
    const i = ordered.findIndex((r) => r.item.id === cur?.item.id)
    const k = e.key.toLowerCase()
    if (k === 'j' || e.key === 'ArrowDown') setSelected(ordered[Math.min(ordered.length - 1, i + 1)]?.item.id)
    else if (k === 'k' || e.key === 'ArrowUp') setSelected(ordered[Math.max(0, i - 1)]?.item.id)
    else if (k === 'a') decide('approve')
    else if (k === 'r') decide('reject')
    else if (k === 'e') decide('escalate')
    else return
    e.preventDefault()
  }

  const blocked = cur?.judged ? cannotDecide(cur.item, cur.judged, reviewer) : 'Checking the plan…'
  const mine = cur?.judged?.valid.some((d) => d.by === reviewer)
  const hideOthers = blind && cur && !mine && cur.item.needs > 1 && reviewer !== cur.item.requester
  const left = cur?.item.expiresAt ? new Date(cur.item.expiresAt).getTime() - clock.getTime() : null

  return (
    <section className={cx('ic', className)} aria-label={title}>
      <div className="ic-head-row">
        <div>
          <h3 className="ic-title" style={{ margin: 0 }}>{title}</h3>
          <div className="ic-sub">{open} waiting for a decision · you are {reviewer}</div>
        </div>
      </div>
      <div className="ic-queue-body" ref={body} tabIndex={0} onKeyDown={onKey} aria-label="Approval queue. J and K move, A approves, R rejects, E escalates.">
        <ul className="ic-list ic-qlist" role="listbox" aria-label="Requests">
          {ordered.map(({ item, judged }) => {
            const s = judged ? STATUS_WORD[judged.status] : { text: 'Checking…' as string, tone: undefined }
            return (
              <li key={item.id} role="option" aria-selected={cur?.item.id === item.id} data-selected={cur?.item.id === item.id} className="ic-qitem" onClick={() => { setSelected(item.id); body.current?.focus() }}>
                <i className="ic-risk" data-risk={item.risk} title={`${item.risk} risk`} />
                <div className="ic-qmain">
                  <div className="ic-qtitle"><b>{item.action}</b></div>
                  <div className="ic-sub ic-ell">{item.requester}{item.amountLabel ? ` · ${item.amountLabel}` : ''}</div>
                  <span className="ic-pill" data-tone={s.tone} style={{ marginTop: 4 }}>{s.text}</span>
                </div>
              </li>
            )
          })}
        </ul>

        {cur && (
          <div className="ic-qdetail" aria-live="polite">
            <div className="ic-head-row" style={{ marginBottom: 4 }}>
              <div>
                <strong style={{ fontSize: 16 }}>{cur.item.action}</strong>
                <div className="ic-sub">Asked by {cur.item.requester}{cur.item.amountLabel ? ` · ${cur.item.amountLabel}` : ''} · {cur.item.risk} risk</div>
              </div>
              {cur.judged && <span className="ic-pill" data-tone={STATUS_WORD[cur.judged.status].tone}>{STATUS_WORD[cur.judged.status].text}</span>}
            </div>
            <p style={{ margin: '6px 0' }}>{cur.item.summary}</p>
            {cur.judged && <p className="ic-statusline" data-status={cur.judged.status}>{cur.judged.reason}</p>}

            <div className="ic-qgrid">
              <div>
                <div className="ic-qhead">What will happen</div>
                <JsonTree value={cur.item.plan} label="plan" defaultExpandDepth={2} />
                <div className="ic-sub" style={{ marginTop: 6 }} title="Your approval is bound to this exact plan. If the plan changes, the approval stops counting.">
                  Bound to plan <b className="ic-id">{cur.hash ? cur.hash.slice(0, 12) : '…'}</b>
                </div>
              </div>
              <div>
                <div className="ic-qhead">Evidence checked</div>
                <ul className="ic-list ic-evidence">
                  {cur.item.evidence.map((e) => (
                    <li key={e.label} data-ok={e.ok}><span aria-hidden="true">{e.ok ? <Check /> : <Cross />}</span><span><span className="ic-sr">{e.ok ? 'Passed: ' : 'Failed: '}</span>{e.label}{e.detail && <span className="ic-sub"> · {e.detail}</span>}</span></li>
                  ))}
                </ul>
                <div className="ic-qhead" style={{ marginTop: 10 }}>If you approve</div>
                <p style={{ margin: 0 }} className="ic-chips">
                  {cur.item.reversible === false ? <span className="ic-pill" data-tone="bad">Cannot be undone</span> : <span className="ic-pill">{cur.item.reversible.undoUntil ? `Undo until ${formatWhen(cur.item.reversible.undoUntil)}` : 'Can be undone'}</span>}
                  {left !== null && <span className="ic-pill" data-tone={left > 0 ? 'warn' : 'bad'} title="If nobody decides in time it expires and nothing happens.">{left > 0 ? `Expires in ${formatDuration(left)}` : 'Expired'}</span>}
                </p>
              </div>
            </div>

            <div className="ic-qhead" style={{ marginTop: 12 }}>Approvals {cur.judged?.valid.filter((d) => d.decision === 'approve').length ?? 0} of {cur.item.needs}</div>
            {hideOthers ? <p className="ic-sub" style={{ margin: '4px 0 0' }}>Other reviewers' decisions are hidden until you decide, so yours is your own judgement.</p> : (
              <ul className="ic-list ic-dlog">
                {cur.item.decisions.length === 0 && <li className="ic-sub">No decisions yet.</li>}
                {cur.item.decisions.map((d, i) => {
                  const bad = cur.judged?.ignored.find((x) => x.decision === d)
                  return <li key={i} data-ignored={!!bad}><b>{d.by}</b> {d.decision === 'approve' ? 'approved' : d.decision === 'reject' ? 'rejected' : 'escalated'} <span className="ic-sub">{formatWhen(d.at)}</span> <span className="ic-id ic-sub">{d.planHash.slice(0, 8)}</span>{bad && <span className="ic-ignored"> · does not count: {bad.why}</span>}</li>
                })}
              </ul>
            )}

            <div className="ic-actions">
              <button type="button" className="ic-btn" data-kind="approve" disabled={!!blocked} onClick={() => decide('approve')}>{cur.item.approveLabel ?? `Approve: ${cur.item.action}`}<kbd>A</kbd></button>
              <button type="button" className="ic-btn" data-kind="reject" disabled={!!blocked} onClick={() => decide('reject')}>Reject<kbd>R</kbd></button>
              <button type="button" className="ic-btn" disabled={!!blocked} onClick={() => decide('escalate')}>Escalate<kbd>E</kbd></button>
            </div>
            {blocked && <p className="ic-sub" style={{ margin: '6px 0 0' }}>{blocked}</p>}
          </div>
        )}
      </div>
    </section>
  )
}

// Rules for an approval queue. The point of each: an approval must be about the exact thing that happens.
import { canonical, sha256Hex } from '../verify/canonical'

export type DecisionKind = 'approve' | 'reject' | 'escalate'
export type Decision = { by: string; decision: DecisionKind; at: string; planHash: string }
export type QueueItem = {
  id: string
  action: string
  summary: string
  requester: string
  amountLabel?: string
  risk: 'low' | 'medium' | 'high'
  /** The exact thing that will happen if this is approved. Its hash is what an approval is bound to. */
  plan: unknown
  expiresAt?: string
  evidence: { label: string; ok: boolean; detail?: string }[]
  /** `false` means it cannot be undone. */
  reversible: { undoUntil?: string } | false
  /** Approvals needed from different people. */
  needs: number
  decisions: Decision[]
  approveLabel?: string
}
export type ItemStatus = 'pending' | 'partial' | 'approved' | 'rejected' | 'escalated' | 'expired' | 'stale'
export type Judged = { status: ItemStatus; valid: Decision[]; ignored: { decision: Decision; why: string }[]; reason: string }

export const planDigest = (plan: unknown) => sha256Hex(canonical(plan))

/**
 * Works out where an item stands. A decision only counts if it was made on the plan as it is now, was made by
 * someone other than the requester, and is the first from that person. A person's earlier approval of an old
 * version of the plan never counts toward the new one.
 */
export function judgeItem(item: QueueItem, currentHash: string, now: Date): Judged {
  const valid: Decision[] = []
  const ignored: Judged['ignored'] = []
  const seen = new Set<string>()
  for (const d of item.decisions) {
    if (d.planHash !== currentHash) ignored.push({ decision: d, why: 'The plan changed after this decision, so it no longer counts.' })
    else if (d.by === item.requester) ignored.push({ decision: d, why: 'The person who asked cannot approve their own request.' })
    else if (seen.has(d.by)) ignored.push({ decision: d, why: 'This person already decided.' })
    else {
      seen.add(d.by)
      valid.push(d)
    }
  }
  const approvals = valid.filter((d) => d.decision === 'approve').length
  const staleApprovals = ignored.filter((i) => i.decision.decision === 'approve' && i.why.startsWith('The plan changed')).length
  const need = Math.max(1, item.needs)
  if (valid.some((d) => d.decision === 'reject')) return { status: 'rejected', valid, ignored, reason: 'A reviewer rejected this.' }
  if (approvals >= need) return { status: 'approved', valid, ignored, reason: `${approvals} of ${need} approvals, all on the current plan.` }
  if (valid.some((d) => d.decision === 'escalate')) return { status: 'escalated', valid, ignored, reason: 'Handed to someone with more authority.' }
  if (item.expiresAt && new Date(item.expiresAt).getTime() <= now.getTime()) return { status: 'expired', valid, ignored, reason: 'Nobody decided in time, so nothing happens.' }
  if (staleApprovals > 0) return { status: 'stale', valid, ignored, reason: `${staleApprovals} earlier ${staleApprovals === 1 ? 'approval was' : 'approvals were'} for a different version of the plan. Review it again.` }
  if (approvals > 0) return { status: 'partial', valid, ignored, reason: `${approvals} of ${need} approvals. ${need - approvals} more from a different person.` }
  return { status: 'pending', valid, ignored, reason: need > 1 ? `Needs ${need} approvals from different people.` : 'Waiting for a decision.' }
}

/** Why this person cannot decide right now, or null if they can. */
export function cannotDecide(item: QueueItem, judged: Judged, reviewer: string): string | null {
  if (judged.status === 'approved' || judged.status === 'rejected' || judged.status === 'escalated') return 'This is already decided.'
  if (judged.status === 'expired') return 'This expired. Ask for it again.'
  if (reviewer === item.requester) return 'You asked for this, so someone else has to decide.'
  if (judged.valid.some((d) => d.by === reviewer)) return 'You have already decided on this plan.'
  return null
}

export const RISK_ORDER = { high: 0, medium: 1, low: 2 } as const
export const STATUS_ORDER: Record<ItemStatus, number> = { stale: 0, pending: 1, partial: 2, expired: 3, escalated: 4, approved: 5, rejected: 6 }
